    /**
     * Every generated model has a round-trip case.
     *
     * Counted reflectively, so a model dropped by a bad regeneration fails here rather than
     * quietly reducing what is checked.
     */
    public function testEveryModelHasARoundTripCase(): void
    {
        $reflection = new \ReflectionClass(self::class);
        $cases = array_filter(
            $reflection->getMethods(\ReflectionMethod::IS_PUBLIC),
            static fn (\ReflectionMethod $m): bool => str_ends_with($m->getName(), 'RoundTrips'),
        );

        self::assertCount(204, $cases);
    }
